import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import * as A from '../src/astronomy.mjs';import * as P from '../src/projection.mjs';
import {SkyController,discOccults} from '../src/scene.mjs';
let T={};try{T=await import('../src/time-scales.mjs');}catch{}
const near=(a,b,t=1e-7)=>assert.ok(Math.abs(a-b)<t,`${a} != ${b} [${t}]`);
const obs={utcMs:Date.UTC(2026,9,4),latDeg:28.54,lonDeg:-81.38};
const star={raDeg:101.287,decDeg:-16.716,epochJyear:2000,pmRaCosDecMasYr:-546,pmDecMasYr:-1223,distancePc:2.64,radialVelocityKmS:-5.5};
test('time policy contains historical leap steps and confirmed2026 offset',()=>{assert.equal(typeof T.timeScales,'function');near(T.timeScales(obs).ttMinusUtcSeconds,69.184);near(T.timeScales({...obs,utcMs:Date.UTC(2016,11,31,23,59,59)}).ttMinusUtcSeconds,68.184);near(T.timeScales({...obs,utcMs:Date.UTC(2017,0,1)}).ttMinusUtcSeconds,69.184);});
test('USNO pre1972 UTC drift is honoured rather than a constant modern offset',()=>{assert.equal(typeof T.timeScales,'function');const t=T.timeScales({...obs,utcMs:Date.UTC(1965,0,1)});near(t.ttMinusUtcSeconds,32.184+3.54013+(38761-38761)*.001296,1e-5);});
test('unknown future leap history and preUTC dates are warnings, not fictitious time measurements',()=>{assert.equal(typeof T.timeScales,'function');assert.ok(T.timeScales({...obs,utcMs:Date.UTC(2050,0,1)}).warnings.includes('future-TAI-UTC-assumed-last-confirmed'));assert.ok(T.timeScales({...obs,utcMs:Date.UTC(1950,0,1)}).warnings.includes('pre1961-proleptic-time-with-estimated-deltaT'));});
test('supplied time offsets including truezero override defaults',()=>{assert.equal(typeof T.timeScales,'function');const t=T.timeScales({...obs,dut1Seconds:.4,ttMinusUtcSeconds:0});near(t.ttMinusUtcSeconds,0);near((t.jdUt1-t.jdUtc)*86400,.4,3e-5);});
test('invalid pressure/temp/vector inputs reject even when below horizon',()=>{for(const more of [{pressureHpa:-1},{temperatureC:NaN},{heightM:Infinity},{velocityOverC:[1,0,0]},{earthBarycentric:{positionAu:[1,0,0]}}])assert.throws(()=>A.observationFrame({...obs,...more}));});
test('bounded dates accept1900 and2100calendar boundaries, reject outside',()=>{for(const utcMs of [Date.UTC(1900,0,1),Date.UTC(2100,11,31,23,59,59)])assert.ok(A.observationFrame({...obs,utcMs}));for(const utcMs of [Date.UTC(1899,11,31),Date.UTC(2101,0,1)])assert.throws(()=>A.observationFrame({...obs,utcMs}));});
test('Earth state returns physical AU and AU/day scales',()=>{assert.equal(typeof A.earthState,'function');const e=A.earthState(2461317);assert.ok(Math.hypot(...e.positionAu)>.98&&Math.hypot(...e.positionAu)<1.02);assert.ok(Math.hypot(...e.velocityAuDay)>.016&&Math.hypot(...e.velocityAuDay)<.019);});
test('frame contains precomputed rotation and automatically applied annual/diurnal velocity',()=>{const f=A.observationFrame(obs);assert.equal(f.rotation?.length,3);assert.ok(Math.hypot(...f.velocityOverC)>.00009);assert.ok(f.warnings.includes('heliocentric-earth-approximation'));assert.ok(!f.warnings.includes('annual-aberration-unavailable'));});
test('shared frame snapshots input ownership rather than aliasing mutable observer',()=>{const o={...obs},f=A.observationFrame(o),a=A.observeStar(star,f);o.utcMs+=86400000;o.latDeg=80;const b=A.observeStar(star,f);assert.deepEqual(a,b);});
test('annual aberration is tens of arcseconds, not degrees or missing',()=>{const a=A.observeStar(star,obs),b=A.observeStar(star,{...obs,aberration:false});const d=A.angularSeparation(A.radecVector(a.raOfDateDeg,a.decOfDateDeg),A.radecVector(b.raOfDateDeg,b.decOfDateDeg))*3600;assert.ok(d>2&&d<22,d);});
test('nearby sources receive parallax without altering their catalogue magnitude',()=>{const a=A.observeStar(star,{...obs,aberration:false}),b=A.observeStar(star,{...obs,aberration:false,parallax:false});const d=A.angularSeparation(a.enu,b.enu)*3600;assert.ok(d>.01&&d<.5,d);assert.equal(a.parallaxApplied,true);});
test('missing parallax remains explicit and exact zero proper motion is valid',()=>{const h=A.observeStar({...star,distancePc:null,pmRaCosDecMasYr:0,pmDecMasYr:0},obs);assert.equal(h.parallaxApplied,false);assert.ok(h.warnings.includes('distance-unavailable-parallax-not-applied'));assert.ok(!h.warnings.includes('proper-motion-unavailable'));});
test('external barycentric state requires timestamp/frame and displaces analytic state',()=>{assert.throws(()=>A.observationFrame({...obs,earthBarycentric:{jdTt:2461317,frame:'ICRS',positionAu:[1,0,0],velocityAuDay:[0,.017,0]}}));});
test('refracted ENU agrees with displayed altitude, geometric ENU retained',()=>{const f=A.observationFrame({...obs,meanOnly:true,pressureHpa:1010}),s={raDeg:f.lstDeg+87,decDeg:0};const h=A.observeStar(s,f);assert.ok(h.refractionDeg>0);near(Math.asin(h.enu[2])/A.DEG,h.altDeg,1e-8);near(Math.asin(h.enuGeometric[2])/A.DEG,h.geometricAltDeg,1e-8);});
test('perspective forward/inverse roundtrips at poles and camera roll',()=>{assert.equal(typeof P.unprojectPerspective,'function');for(const alt of [-90,0,45,90])for(const roll of [0,30,90,180]){const c={width:325,height:530,azDeg:355,altDeg:alt,rollDeg:roll,fovYDeg:100};for(const [x,y] of [[162.5,265],[0,0],[325,530],[70,90]]){const h=P.unprojectPerspective(x,y,c),p=P.projectPerspective(h,c);near(p.x,x,1e-7);near(p.y,y,1e-7);}}});
test('projection refuses impossible dimensions and invalid directions',()=>{for(const c of [{width:0},{height:NaN},{rollDeg:Infinity},{fovYDeg:180}])assert.throws(()=>P.projectPerspective({altDeg:40,azDeg:180},c));assert.throws(()=>P.projectAllSky({altDeg:40,azDeg:180},{width:10,padding:6}));assert.throws(()=>P.unprojectAllSky(NaN,10));});
test('camera orientation and field of view do not relocate stars',()=>{const c={width:325,height:530,azDeg:180,altDeg:0,fovYDeg:90};const right=P.projectPerspective({altDeg:0,azDeg:190},c),up=P.projectPerspective({altDeg:10,azDeg:180},c);assert.ok(right.x>162.5);assert.ok(up.y<265);const cr=P.projectPerspective({altDeg:10,azDeg:180},{...c,rollDeg:90});assert.ok(cr.x>162.5);});
test('physical newMoon is opaque regardless illumination/calendarMoon screen position',()=>{assert.equal(discOccults({azDeg:10,altDeg:20},{azDeg:10,altDeg:20,radiusDeg:.25,illumination:0}),true);assert.equal(discOccults({azDeg:12,altDeg:20},{azDeg:10,altDeg:20,radiusDeg:.25}),false);});
test('typed correction switches reject strings instead of turning false text into true',()=>{for(const [k,v] of [['meanOnly','true'],['parallax','false'],['aberration',1]])assert.throws(()=>A.observationFrame({...obs,[k]:v}));});
test('legacy projection also rejects invalid standalone directions',()=>{for(const h of [{altDeg:NaN,azDeg:0},{altDeg:0,azDeg:Infinity}])assert.throws(()=>P.projectWidgetDome(h));});
test('one provided total velocity is never double-added to analytic annual/diurnal terms',()=>{const b=[0,.0001,0],f=A.observationFrame({...obs,velocityOverC:b});assert.deepEqual(f.velocityOverC,b);b[1]=0;assert.equal(f.velocityOverC[1],.0001);});
test('external reference state does not masquerade as ordinary static epoch data',()=>{const o={...obs,earthBarycentric:{jdTt:2461317,frame:'galactic',positionAu:[1,0,0],velocityAuDay:[0,.017,0]}};assert.throws(()=>A.observationFrame(o));});
